  --surface-page:    #fbfaf6;
  --surface-panel:   #ffffff;
  --surface-sunken:  #f1eee6;

  /* ink */
  --ink-primary:    #0e1116;
  --ink-secondary:  #454a52;
  --ink-tertiary:   #7d838c;

  /* rules */
  --rule:         #d6d3ca;
  --rule-strong:  #b3afa2;

  /* accents */
  --accent-cyan:   #0a8e8e;
  --accent-amber:  #c46a00;
  --accent-green:  #1f7a3f;
  --accent-red:    #b22b2b;
  --accent-violet: #5e3aa8;

  /* fonts */
  --font-sans: "Inter Variable", "Inter", -apple-system, BlinkMacSystemFont,
               "Segoe UI", Roboto, system-ui, sans-serif;
  --font-mono: "JetBrains Mono Variable", "JetBrains Mono",
               ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;

  /* type scale */
  --text-xs:   0.75rem;
  --text-sm:   0.875rem;
  --text-base: 1rem;
  --text-lg:   1.125rem;
  --text-xl:   1.25rem;
  --text-2xl:  1.5625rem;
  --text-3xl:  1.953rem;
  --text-4xl:  2.441rem;

  /* spacing */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 24px;
  --space-6: 32px;
  --space-7: 48px;
  --space-8: 64px;

  /* radii */
  --radius-sm: 2px;
  --radius-md: 4px;
  --radius-lg: 8px;
}

.dark {
  --surface-page:   #0a0e14;
  --surface-panel:  #10151d;
  --surface-sunken: #070a0f;

  --ink-primary:   #e6edf3;
  --ink-secondary: #9ea7b3;
  --ink-tertiary:  #5e6772;

  /* hairline rules: previous #1e2530 was nearly invisible against
   * the page bg. Lift to a value that reads as a true 1px instrument
   * panel seam without becoming obtrusive. */
  --rule:        #262e3a;
  --rule-strong: #3d4756;

  --accent-cyan:   #4dd4cf;
  --accent-amber:  #ffb454;
  --accent-green:  #7ce38b;
  --accent-red:    #ff7b7b;
  --accent-violet: #a78bfa;
}

/* ---- baseline ---- */

html, body {
  background: var(--surface-page);
  color: var(--ink-primary);
  font-family: var(--font-sans);
  font-size: 16px;        /* hard floor — Hextra sometimes drops this on mobile */
  font-feature-settings: "ss01", "cv01", "cv11";  /* Inter stylistic sets */
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

/* Hextra's prose container */
article, .hextra-content, main {
  font-size: var(--text-base);
  line-height: 1.65;
  color: var(--ink-primary);
}

article p, main p {
  font-size: var(--text-base);
  max-width: 70ch;
}

/* The 70ch cap is a prose comfort target, not a global constraint.
 * Code blocks, tables, instrument readouts and figures need full width. */
article pre, article table, article figure, article blockquote,
article .bench-readout, article .bench-comparison,
main pre, main table, main figure, main blockquote {
  max-width: none;
}

/* Tabular numerals + slashed zero everywhere a measurement appears.
 * This is the single biggest density/legibility win in instrument UI. */
.bench-readout, .bench-comparison, .br-body table,
.br-body .machine, .br-body .meta {
  font-variant-numeric: tabular-nums slashed-zero;
}

article a, main a {
  color: var(--accent-cyan);
  text-decoration-thickness: 1px;
  text-underline-offset: 2px;
}
article a:hover, main a:hover {
  text-decoration-thickness: 2px;
}

article code, main code,
.hextra-content code {
  font-family: var(--font-mono);
  font-size: 0.92em;
  background: var(--surface-sunken);
  border: 1px solid var(--rule);
  border-radius: var(--radius-sm);
  padding: 1px 5px;
}

/* fenced code blocks: keep Hextra/highlight chrome but enforce mono + size */
article pre, main pre, .hextra-content pre {
  font-family: var(--font-mono);
  font-size: var(--text-sm);
  background: var(--surface-sunken) !important;
  border: 1px solid var(--rule);
  border-radius: var(--radius-md);
  padding: var(--space-4);
}
article pre code, main pre code {
  background: transparent;
  border: none;
  padding: 0;
}

/* ---- headings ---- */

h1, h2, h3, h4, h5, h6,
.hextra-content h1, .hextra-content h2, .hextra-content h3,
article h1, article h2, article h3 {
  font-family: var(--font-mono);
  font-weight: 500;
  letter-spacing: -0.01em;
  color: var(--ink-primary);
  line-height: 1.25;
}

h1, article h1 { font-size: var(--text-3xl); margin-top: var(--space-7); margin-bottom: var(--space-5); }
h2, article h2 { font-size: var(--text-2xl); margin-top: var(--space-7); margin-bottom: var(--space-4);
                 padding-bottom: var(--space-2); border-bottom: 1px solid var(--rule-strong); }
h3, article h3 { font-size: var(--text-xl);  margin-top: var(--space-5); margin-bottom: var(--space-3); }
h4, h5, h6     { font-size: var(--text-lg);  margin-top: var(--space-4); margin-bottom: var(--space-2); }

/* ---- navbar (Hextra) ---- */

.hextra-nav-container {
  background: var(--surface-page);
  border-bottom: 1px solid var(--rule);
  backdrop-filter: none;       /* lose the gauzy blur Hextra ships with */
}
/* Hextra paints a separate ::before-style blur layer; neutralize it so
 * the navbar reads as a flat instrument-bezel surface in both modes. */
.hextra-nav-container .hextra-nav-container-blur,
.hextra-nav-container-blur {
  background: var(--surface-page) !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
}

.hextra-nav-container a,
.hextra-nav-container .nx-text-base {
  font-family: var(--font-mono);
  font-size: var(--text-sm);
  letter-spacing: -0.005em;
  color: var(--ink-primary);
}

.hextra-nav-container a:hover {
  color: var(--accent-cyan);
}

/* brand title in navbar */
.hextra-nav-container [class*="logo"], .hextra-nav-container .nx-font-bold {
  font-family: var(--font-mono);
  font-weight: 500;
  letter-spacing: -0.02em;
}

/* ---- left sidebar (docs) ---- */

aside, .nextra-sidebar, [class*="sidebar"] {
  border-right: 1px solid var(--rule);
}
aside a, .nextra-sidebar a {
  font-family: var(--font-sans);
  font-size: var(--text-sm);
  color: var(--ink-secondary);
}
aside a:hover, .nextra-sidebar a:hover {
  color: var(--accent-cyan);
}
aside a.active, .nextra-sidebar a[aria-current="page"] {
  color: var(--accent-cyan);
  font-weight: 500;
}

/* ---- right TOC ---- */

.toc, [class*="toc"] {
  font-family: var(--font-mono);
  font-size: var(--text-xs);
}

/* ---- hero (homepage) ---- */

.hextra-hero, [class*="hero-headline"] {
  font-family: var(--font-mono) !important;
  font-weight: 500 !important;
  letter-spacing: -0.02em !important;
}

[class*="hero-subtitle"] {
  font-family: var(--font-sans);
  color: var(--ink-secondary);
  font-size: var(--text-lg);
}

  color: var(--ink-secondary);
}

/* ---- live bench readout (3-panel) ---- */

.hero-readout-wrap {
  max-width: 980px;
  margin: 0 auto var(--space-7);
  padding: 0 var(--space-5);
}

.bench-readout {
  margin-top: var(--space-3);
  padding: var(--space-5);
  background: var(--surface-panel);
  border: 1px solid var(--rule);
  border-radius: var(--radius-md);
  text-align: left;
  max-width: 100%;
}

.bench-readout__eyebrow {
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink-secondary);
  margin-bottom: var(--space-4);
  display: flex;
  align-items: center;
  gap: var(--space-2);
  flex-wrap: wrap;
}
/* Amber "live" dot before the LATEST eyebrow — per DESIGN.md amber is
 * the now-marker. Slow pulse signals fresh data without becoming a
 * status-page distraction. */
.bench-readout__eyebrow::before {
  content: "";
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--accent-amber);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--accent-amber) 18%, transparent);
  flex-shrink: 0;
  animation: live-pulse 2.4s ease-in-out infinite;
}
@keyframes live-pulse {
  0%, 100% { opacity: 1;   box-shadow: 0 0 0 2px color-mix(in srgb, var(--accent-amber) 18%, transparent); }
  50%      { opacity: 0.6; box-shadow: 0 0 0 4px color-mix(in srgb, var(--accent-amber)  6%, transparent); }
}
@media (prefers-reduced-motion: reduce) {
  .bench-readout__eyebrow::before { animation: none; }
}
.bench-readout__ts {
  color: var(--ink-tertiary);
  text-transform: none;
  letter-spacing: 0;
  font-feature-settings: "tnum";
}

.bench-readout__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-5);
}
@media (max-width: 720px) {
  .bench-readout__grid {
    grid-template-columns: 1fr;
    gap: var(--space-3);
  }
}

.bench-readout__panel {
  border-left: 2px solid var(--accent-cyan);
  padding: var(--space-2) var(--space-4);
  text-align: left;
  position: relative;
  min-width: 0;
}
/* On stacked layouts the vertical rule reads as nothing — flip it to
 * a top rule so each readout still feels like its own gauge. */
@media (max-width: 720px) {
  .bench-readout__panel {
    border-left: none;
    border-top: 2px solid var(--accent-cyan);
    padding: var(--space-3) 0 0 0;
  }
}

.bench-readout__label {
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  letter-spacing: 0.12em;
  color: var(--ink-secondary);
  margin-bottom: var(--space-1);
}

.bench-readout__value {
  font-family: var(--font-mono);
  font-size: 2.45rem;
  font-weight: 500;
  letter-spacing: 0;
  color: var(--accent-cyan);
  line-height: 1.05;
  font-feature-settings: "tnum";
  margin-bottom: var(--space-1);
}

.bench-readout__unit-inline {
  font-size: 0.55em;
  color: var(--ink-tertiary);
  margin-left: 2px;
  letter-spacing: 0;
}

.bench-readout__unit {
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  color: var(--ink-tertiary);
  overflow-wrap: anywhere;
}

.bench-readout__footer {
  margin-top: var(--space-5);
  padding-top: var(--space-3);
  border-top: 1px solid var(--rule);
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  color: var(--ink-tertiary);
  line-height: 1.5;
  overflow-wrap: anywhere;
}
.bench-readout__footer a {
  color: var(--accent-cyan);
  margin-left: var(--space-2);
}

/* ---- features ---- */

.features {
  max-width: 1100px;
  margin: var(--space-8) auto var(--space-7);
  padding: 0 var(--space-5);
}

.features__title {
  font-family: var(--font-mono);
  font-size: var(--text-2xl);
  font-weight: 500;
  letter-spacing: -0.01em;
  margin: 0 0 var(--space-2);
  color: var(--ink-primary);
}

.features__lede {
  font-family: var(--font-sans);
  font-size: var(--text-base);
  color: var(--ink-secondary);
  max-width: 70ch;
  margin: 0 0 var(--space-5);
  line-height: 1.6;
}

.features__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-4);
}
@media (max-width: 980px) { .features__grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 640px) { .features__grid { grid-template-columns: 1fr; } }

.feature {
  --feature-accent: var(--accent-cyan);
  background: var(--surface-panel);
  border: 1px solid var(--rule);
  border-radius: var(--radius-md);
  padding: var(--space-5);
  position: relative;
  transition: border-color 140ms ease, transform 140ms ease;
}
/* Instrument-panel detail: a 2px top accent rule that picks up the
 * card's category color. Sits inside the border (radius-aware). */
.feature::before {
  content: "";
  position: absolute;
  top: -1px;
  left: -1px;
  right: -1px;
  height: 2px;
  background: var(--feature-accent);
  opacity: 0;
  transition: opacity 160ms ease;
  border-radius: var(--radius-md) var(--radius-md) 0 0;
}
.feature:hover {
  border-color: var(--feature-accent);
}
.feature:hover::before { opacity: 1; }

/* Color rotation across the grid — cyan / amber / violet — so a row
 * of features reads like a gauge cluster, not a single message. */
.features__grid > .feature:nth-child(3n+2) { --feature-accent: var(--accent-amber); }
.features__grid > .feature:nth-child(3n+3) { --feature-accent: var(--accent-violet); }

.feature__label {
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  letter-spacing: 0.1em;
  color: var(--feature-accent);
  margin-bottom: var(--space-2);
  text-transform: uppercase;
}

.feature h3 {
  font-family: var(--font-mono);
  font-size: var(--text-lg);
  font-weight: 500;
  letter-spacing: -0.01em;
  margin: 0 0 var(--space-2);
  color: var(--ink-primary);
  border-bottom: none;
  padding-bottom: 0;
}

.feature p {
  font-family: var(--font-sans);
  font-size: var(--text-sm);
  color: var(--ink-secondary);
  line-height: 1.55;
  margin: 0;
}

.feature code {
  font-family: var(--font-mono);
  font-size: 0.92em;
  background: var(--surface-sunken);
  border: 1px solid var(--rule);
  border-radius: var(--radius-sm);
  padding: 1px 5px;
}

/* ---- origin / footer-credit section ---- */

.origin {
  max-width: 720px;
  margin: var(--space-8) auto;
  padding: var(--space-5);
  text-align: center;
  border-top: 1px solid var(--rule);
  border-bottom: 1px solid var(--rule);
}
.origin p {
  font-family: var(--font-sans);
  font-size: var(--text-sm);
  color: var(--ink-tertiary);
  line-height: 1.65;
  margin: 0;
}

/* ---- wheel mark ---- */

.wheel-mark {
  display: inline-block;
  vertical-align: middle;
}
.wheel-mark--spin {
  animation: wheel-spin 4s linear infinite;
  transform-origin: center;
}
@keyframes wheel-spin {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}

/* ====================================================================
 * BENCHMARKS LANDING — bench-comparison panel
 * ==================================================================== */

.bench-comparison {
  margin: var(--space-6) 0;
  font-family: var(--font-sans);
  max-width: 100%;
}

.bench-comparison__stat-row {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: var(--space-3);
  margin-bottom: var(--space-6);
  padding: var(--space-4);
  background: var(--surface-panel);
  border: 1px solid var(--rule);
  border-radius: var(--radius-md);
}
@media (max-width: 720px) {
  .bench-comparison__stat-row { grid-template-columns: repeat(2, 1fr); }
}

.bench-comparison__stat {
  text-align: center;
  border-left: 1px solid var(--rule);
  padding: 0 var(--space-3);
  min-width: 0;
}
.bench-comparison__stat:first-child { border-left: none; }

.bench-comparison__stat-num {
  font-family: var(--font-mono);
  font-size: var(--text-2xl);
  font-weight: 500;
  color: var(--accent-cyan);
  letter-spacing: 0;
  font-feature-settings: "tnum";
  font-variant-numeric: tabular-nums slashed-zero;
  line-height: 1.1;
}
.bench-comparison__stat-label {
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink-secondary);
  margin-top: var(--space-2);
  line-height: 1.3;
  overflow-wrap: anywhere;
}
/* Make the second stat (active profiles, "live") amber so the
 * 4-stat row reads as cyan/amber/violet/neutral — visual rhythm
 * that maps to the chart palette. */
.bench-comparison__stat:nth-child(2) .bench-comparison__stat-num { color: var(--accent-amber); }
.bench-comparison__stat:nth-child(3) .bench-comparison__stat-num { color: var(--accent-violet); }
.bench-comparison__stat:nth-child(4) .bench-comparison__stat-num { color: var(--ink-secondary); }

.bench-comparison__block {
  margin: var(--space-6) 0;
  padding: var(--space-4) var(--space-5);
  background: var(--surface-panel);
  border: 1px solid var(--rule);
  border-radius: var(--radius-md);
}

.bench-comparison__title {
  font-family: var(--font-mono);
  font-size: var(--text-base);
  font-weight: 500;
  color: var(--ink-primary);
  margin-bottom: var(--space-2);
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.bench-comparison__caption {
  font-family: var(--font-sans);
  font-size: var(--text-sm);
  color: var(--ink-secondary);
  line-height: 1.55;
  margin-bottom: var(--space-4);
  max-width: 75ch;
  overflow-wrap: anywhere;
}
.bench-comparison__caption code {
  font-family: var(--font-mono);
  font-size: 0.92em;
  background: var(--surface-sunken);
  border: 1px solid var(--rule);
  padding: 1px 5px;
  border-radius: var(--radius-sm);
}

.bench-comparison__table {
  width: 100%;
  max-width: 100%;
  display: block;
  overflow-x: auto;
  overscroll-behavior-x: contain;
  border-collapse: collapse;
  font-family: var(--font-mono);
  font-size: var(--text-sm);
  font-variant-numeric: tabular-nums slashed-zero;
  border: 1px solid var(--rule);
  scrollbar-color: var(--rule-strong) var(--surface-sunken);
  scrollbar-width: thin;
}
.bench-comparison__table th {
  text-align: right;
  padding: var(--space-2) var(--space-3);
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ink-secondary);
  border-bottom: 2px solid var(--rule-strong);
  background: transparent;
  font-weight: 500;
  white-space: nowrap;
}
.bench-comparison__table th:first-child,
.bench-comparison__table td:first-child {
  text-align: left;
  min-width: 18ch;
  max-width: 30ch;
  white-space: normal;
  overflow-wrap: anywhere;
}
.bench-comparison__table td {
  padding: var(--space-3);
  border-bottom: 1px solid var(--rule);
  text-align: right;
  color: var(--ink-primary);
  font-feature-settings: "tnum";
  line-height: 1.45;
  vertical-align: top;
  white-space: nowrap;
}
.bench-comparison__table tbody tr:last-child td {
  border-bottom: none;
}
.bench-comparison__table tbody tr {
  transition: background-color 100ms ease;
}
.bench-comparison__table tr:hover td {
  background: var(--surface-sunken);
}
/* The pass@k column is the headline metric in both comparison tables —
 * it's column 2 in qwen-across-providers and column 3 in
 * frontier-comparators (always the last column). Signal-color it so
 * the eye finds it without reading column headers. */
.bench-comparison__table td:nth-child(2) {
  color: var(--accent-cyan);
  font-weight: 500;
}
/* Restore default ink for the qwen-across-providers table — pass@k
 * isn't in column 2 there; instead it's followed by ttft/decode/wall
 * cells that should stay neutral. Use a finer selector: only the
 * column that contains a __sub span (which marks pass@k cells). */
.bench-comparison__table td:nth-child(2):not(:has(.bench-comparison__sub)) {
  color: var(--ink-primary);
  font-weight: 400;
}
/* Any pass@k cell (recognized by the .__sub annotation) gets the
 * cyan signal treatment, regardless of column position. */
.bench-comparison__table td:has(.bench-comparison__sub) {
  color: var(--accent-cyan);
  font-weight: 500;
}

.bench-comparison__sub {
  display: inline-block;
  margin-left: var(--space-2);
  color: var(--ink-tertiary);
  font-size: var(--text-xs);
  font-weight: 400;
}

.bench-comparison__via {
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  color: var(--ink-secondary);
  white-space: normal;
  overflow-wrap: anywhere;
}

.bench-comparison__footer {
  margin-top: var(--space-4);
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  color: var(--ink-tertiary);
  text-align: right;
}

/* ---- selection + focus ---- */

::selection {
  /* Translucent cyan so any underlying ink remains legible — solid
   * accent-on-text inverts contrast in unpredictable ways across the
   * mixed mono/sans body. */
  background: color-mix(in srgb, var(--accent-cyan) 32%, transparent);
  color: inherit;
}


---
  grid-template-columns: minmax(8ch, max-content) 1fr;
  gap: var(--space-2) var(--space-4);
  margin: var(--space-4) 0;
  font-size: var(--text-sm);
}
article dt, main dt {
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--ink-secondary);
  align-self: baseline;
}
article dd, main dd {
  margin: 0;
  color: var(--ink-primary);
}

/* ---- mobile polish ---- */

@media (max-width: 640px) {
  .hero { margin-top: var(--space-6); margin-bottom: var(--space-6); }
  .hero__title { letter-spacing: -0.03em; }
  .hero__cta { gap: var(--space-2); }
  .hero__btn { padding: var(--space-3) var(--space-4); }
  .bench-readout { padding: var(--space-4); }
  .bench-readout__value { font-size: 2rem; }
  .bench-comparison__stat-row { padding: var(--space-3); gap: var(--space-2); }
  .bench-comparison__stat { padding: var(--space-2) var(--space-2); }
